-- School numbers: generated by the database only, never by the client.
-- Existing numbers (all 6-digit numeric) are untouched; the sequence starts above the current maximum.
CREATE SEQUENCE IF NOT EXISTS public.student_number_seq AS bigint MINVALUE 1;
SELECT setval('public.student_number_seq',
  GREATEST(COALESCE((SELECT max(student_number::bigint) FROM public.students WHERE student_number ~ '^\d+$'), 0), 100000));
REVOKE ALL ON SEQUENCE public.student_number_seq FROM PUBLIC, anon, authenticated;
GRANT USAGE ON SEQUENCE public.student_number_seq TO service_role;

CREATE OR REPLACE FUNCTION public.student_number_guard()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    -- Ignore any client-supplied value; skip numbers already taken (e.g. older manual ones).
    LOOP
      NEW.student_number := nextval('public.student_number_seq')::text;
      EXIT WHEN NOT EXISTS (SELECT 1 FROM public.students WHERE student_number = NEW.student_number);
    END LOOP;
  ELSIF NEW.student_number IS DISTINCT FROM OLD.student_number THEN
    RAISE EXCEPTION 'الرقم المدرسي يولده النظام ولا يمكن تعديله';
  END IF;
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION public.student_number_guard() FROM PUBLIC, anon, authenticated;

ALTER TABLE public.students ALTER COLUMN student_number SET DEFAULT '';
CREATE TRIGGER student_number_guard BEFORE INSERT OR UPDATE ON public.students
  FOR EACH ROW EXECUTE FUNCTION public.student_number_guard();

-- Open a student file and its yearly enrollment in one transaction (runs with the caller's rights, so RLS applies).
CREATE OR REPLACE FUNCTION public.create_student_with_enrollment(
  _student jsonb, _academic_year uuid, _section uuid, _enrollment_type public.enrollment_type)
RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$
DECLARE sid uuid;
BEGIN
  IF NOT public.can_manage(auth.uid()) THEN RAISE EXCEPTION 'لا تملك صلاحية فتح ملف طالب'; END IF;
  IF _enrollment_type = 'continuing' THEN RAISE EXCEPTION 'الطالب الجديد يُسجَّل كمستجد أو منقول'; END IF;
  IF _enrollment_type = 'transfer_in' AND COALESCE(trim(_student->>'previous_school'), '') = '' THEN
    RAISE EXCEPTION 'اذكر المدرسة السابقة للطالب المنقول';
  END IF;
  INSERT INTO public.students (school_id, full_name, gender, birth_date, national_id, address,
    guardian_name, guardian_relation, guardian_phone, previous_school, notes)
  VALUES ((_student->>'school_id')::uuid, _student->>'full_name', NULLIF(_student->>'gender',''),
    NULLIF(_student->>'birth_date','')::date, NULLIF(_student->>'national_id',''), NULLIF(_student->>'address',''),
    NULLIF(_student->>'guardian_name',''), NULLIF(_student->>'guardian_relation',''), NULLIF(_student->>'guardian_phone',''),
    NULLIF(_student->>'previous_school',''), NULLIF(_student->>'notes',''))
  RETURNING id INTO sid;
  INSERT INTO public.enrollments (student_id, academic_year_id, section_id, enrollment_type)
  VALUES (sid, _academic_year, _section, _enrollment_type);
  RETURN sid;
END $$;
REVOKE ALL ON FUNCTION public.create_student_with_enrollment(jsonb, uuid, uuid, public.enrollment_type) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.create_student_with_enrollment(jsonb, uuid, uuid, public.enrollment_type) TO authenticated;